CREATE TABLE IF NOT EXISTS `api_keys` (`id` int AUTO_INCREMENT NOT NULL, `userId` int NOT NULL, `name` varchar(100) NOT NULL, `tokenHash` varchar(128) NOT NULL, `scopesJson` text NOT NULL, `lastUsedAt` timestamp NULL, `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, `revokedAt` timestamp NULL, CONSTRAINT `api_keys_id` PRIMARY KEY(`id`), CONSTRAINT `api_keys_tokenHash_unique` UNIQUE(`tokenHash`));
